sys.path.insert(0,"/workspace")
from verl.utils.reward_score import gsm8k

def analyze(path, label):
    n=0
    strict_ok=0
    flex_ok=0
    # categories of flex fail when last number numerically equals gt
    num_eq_str_ne=0
    reasons={}
    examples=[]
    # also: strict finds #### but string mismatch
    strict_found=0
    no_hash=0
    hash_wrong_num=0
    hash_format_mismatch=0
    with open(path) as f:
        for line in f:
            r=json.loads(line)
            out=r["output"]
            gt=str(r["gts"])
            n+=1
            a_s=gsm8k.extract_solution(out, method="strict")
            a_f=gsm8k.extract_solution(out, method="flexible")
            if a_s is not None:
                strict_found+=1
            if gsm8k.compute_score(out, gt, method="strict")>0:
                strict_ok+=1
            if gsm8k.compute_score(out, gt, method="flexible")>0:
                flex_ok+=1
            else:
                # why
                if a_f is None:
                    reasons["none"]=reasons.get("none",0)+1
                else:
                    # numeric?
                    def tofloat(x):
                        try:
                            return float(str(x).replace(",","").replace("$",""))
                        except: return None
                    fa, fg = tofloat(a_f), tofloat(gt)
                    if fa is not None and fg is not None and abs(fa-fg)<1e-6:
                        num_eq_str_ne += 1
                        # reason
                        if "," in str(a_f) and "," not in gt:
                            reasons["comma"]=reasons.get("comma",0)+1
                        elif str(a_f).endswith(".0") or str(a_f).endswith(".00"):
                            reasons["decimal"]=reasons.get("decimal",0)+1
                        elif "$" in str(a_f):
                            reasons["dollar"]=reasons.get("dollar",0)+1
                        else:
                            reasons["other_numeq"]=reasons.get("other_numeq",0)+1
                            if len(examples)<6:
                                examples.append(("numeq", gt, a_f, a_s, out[-180:].replace("\n"," | ")))
                    else:
                        reasons["wrong"]=reasons.get("wrong",0)+1
    print(f"\n{label} n={n} strict_found {strict_found/n:.3f} strict_ok {strict_ok/n:.3f} flex_ok {flex_ok/n:.3f} num_eq_but_str_ne {num_eq_str_ne}")
    print("  fail reasons", reasons)
    for e in examples:
        print("  ", e)

