"""GSM8K reward aligned with the held-out grader.

The held-out grader marks a response correct only when the last number in the
full response equals the gold answer numerically. Training uses the same rule
over the whole string (not a clipped tail) and compares numerically, so a
correct answer written as ``24.`` or ``57,500`` is not treated as wrong.
"""

import re

_NUM_RE = re.compile(r"-?\d[\d,]*(?:\.\d+)?")


def _normalize(text):
    return str(text).replace(",", "").replace("$", "").strip()


def _to_float(text):
    try:
        return float(_normalize(text))
    except (TypeError, ValueError):
        return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    """1.0 iff the last number in the full response equals the gold answer."""
    if solution_str is None:
        return 0.0
    matches = _NUM_RE.findall(str(solution_str))
    if not matches:
        return 0.0
    pred = _to_float(matches[-1])
    gold = _to_float(ground_truth)
    if pred is None or gold is None:
        return 0.0
    return 1.0 if abs(pred - gold) < 1e-6 else 0.0

